''','''// Version is the version Save writes.
const Version = 3

// ErrUnsupportedVersion is returned for a file of a version this Tally cannot read.
var ErrUnsupportedVersion = errors.New("unsupported snapshot version")

// Version 3 keeps the invoice numbers and each organization's next number (store.State.InvoiceNext). Version 2 had neither.
type fileV3 struct {
	Version int         `json:"version"`
	SavedAt time.Time   `json:"saved_at"`
	State   store.State `json:"state"`
}

type fileV2 struct {
	Version int         `json:"version"`
	SavedAt time.Time   `json:"saved_at"`
	State   store.State `json:"state"`
}

// Save writes everything in st to path, atomically: see writeAtomic.
func Save(st *store.Store, path string, now time.Time) error {
	b, err := json.MarshalIndent(fileV3{Version: Version, SavedAt: now.UTC(), State: st.Export()}, "", "  ")
	if err != nil {
		return err
	}
	return writeAtomic(path, append(b, '\\n'))
}

// Load reads a snapshot written by Save, or by an older version of Tally, and returns a store holding it.
func Load(path string) (*store.Store, error) {
	b, err := os.ReadFile(path)
	if err != nil {
		return nil, err
	}
	_, st, err := decode(b)
	if err != nil {
		return nil, fmt.Errorf("snapshot %s: %w", path, err)
	}
	return store.FromState(st)
}

// Upgrade rewrites the snapshot at path as the current version. The original bytes are first copied to
// "<path>.v<old version>.bak", for example tally.json.v2.bak. A file already at the current version is left alone, without
// a backup. A file of a newer version fails with ErrUnsupportedVersion and is not touched.
func Upgrade(path string) error {
	b, err := os.ReadFile(path)
	if err != nil {
		return err
	}
	v, err := versionOf(b)
	if err != nil {
		return fmt.Errorf("snapshot %s: %w", path, err)
	}
	if v == Version {
		return nil
	}
	_, st, err := decode(b)
	if err != nil {
		return fmt.Errorf("snapshot %s: version %d: %w", path, v, err)
	}
	s, err := store.FromState(st)
	if err != nil {
		return fmt.Errorf("snapshot %s: version %d: %w", path, v, err)
	}
	backup := fmt.Sprintf("%s.v%d.bak", path, v)
	old, err := os.ReadFile(backup)
	switch {
	case err == nil && !bytes.Equal(old, b):
		return fmt.Errorf("snapshot %s: %s exists and differs from the file; move it aside first", path, backup)
	case err != nil && !errors.Is(err, os.ErrNotExist):
		return err
	}
	if err := writeAtomic(backup, b); err != nil {
		return err
	}
	return Save(s, path, time.Now())
}

// versionOf returns the version of a snapshot, or ErrUnsupportedVersion when Load cannot read it.
func versionOf(b []byte) (int, error) {
	var head struct {
		Version int `json:"version"`
	}
	if err := json.Unmarshal(b, &head); err != nil {
		return 0, err
	}
	if head.Version < 1 || head.Version > Version {
		return head.Version, fmt.Errorf("%w %d", ErrUnsupportedVersion, head.Version)
	}
	return head.Version, nil
}

// decode returns the version of a snapshot and the state in it, migrated to the current format.
func decode(b []byte) (int, store.State, error) {
	v, err := versionOf(b)
	if err != nil {
		return 0, store.State{}, err
	}
	switch v {
	case 1:
		st, err := migrateV1(b)
		if err != nil {
			return v, store.State{}, fmt.Errorf("version 1: %w", err)
		}
		numberInvoices(&st)
		return v, st, nil
	case 2:
		var f fileV2
		if err := json.Unmarshal(b, &f); err != nil {
			return v, store.State{}, err
		}
		numberInvoices(&f.State)
		return v, f.State, nil
	default:
		var f fileV3
		if err := json.Unmarshal(b, &f); err != nil {
			return v, store.State{}, err
		}
		return v, f.State, nil
	}
}

// numberInvoices gives the invoices of a file that predates invoice numbers their numbers: per organization, in creation
// order (created_at, then ID), so the next invoice continues after the last one.
func numberInvoices(st *store.State) {
	sort.Slice(st.Invoices, func(i, j int) bool {
		a, b := st.Invoices[i], st.Invoices[j]
		if !a.CreatedAt.Equal(b.CreatedAt) {
			return a.CreatedAt.Before(b.CreatedAt)
		}
		return a.ID < b.ID
	})
	st.InvoiceNext = map[string]int{}
	for i := range st.Invoices {
		inv := &st.Invoices[i]
		n := st.InvoiceNext[inv.OrgID]
		if n < 1 {
			n = 1
		}
		inv.Number = store.InvoiceNumber(n)
		st.InvoiceNext[inv.OrgID] = n + 1
	}
}

// writeAtomic replaces the file at path with data. The data goes to a temporary file in the same folder, which is then
// renamed over path, so path always holds either the old file or the whole new one. On failure the temporary file is removed.
func writeAtomic(path string, data []byte) (err error) {
	f, err := os.CreateTemp(filepath.Dir(path), filepath.Base(path)+".tmp-*")
	if err != nil {
		return err
	}
	defer func() {
		if err != nil {
			_ = f.Close()
			_ = os.Remove(f.Name())
		}
	}()
	if _, err = f.Write(data); err != nil {
		return err
	}
	if err = f.Sync(); err != nil {
		return err
	}
	if err = f.Close(); err != nil {
		return err
	}
	if err = os.Rename(f.Name(), path); err != nil {
		return err
	}
	syncDir(filepath.Dir(path))
	return nil
}

// syncDir makes a rename in dir durable. It is best effort, as not every platform can sync a directory.
func syncDir(dir string) {
	d, err := os.Open(dir)
	if err != nil {
		return
	}
	_ = d.Sync()
	_ = d.Close()
}
