	now := time.Date(2026, 2, 1, 12, 0, 0, 0, time.UTC)
	dir := t.TempDir()
	path := filepath.Join(dir, "tally.json")
	if err := Save(store.New(), path, now); err != nil {
		t.Fatal(err)
	}
	before, _ := os.ReadFile(path)
	if err := Upgrade(path); err != nil {
		t.Fatal(err)
	}
	after, _ := os.ReadFile(path)
	if !bytes.Equal(before, after) {
		t.Fatal("Upgrade changed a version 3 file")
	}
	if names := dirNames(t, dir); !reflect.DeepEqual(names, []string{"tally.json"}) {
		t.Fatalf("files = %v; a version 3 file must not get a backup", names)
	}
