func TestUpgradeVersion2(t *testing.T) {
	dir := t.TempDir()
	path := filepath.Join(dir, "tally.json")
	copyFile(t, filepath.Join("testdata", "v2.json"), path)
	original, err := os.ReadFile(path)
	if err != nil {
		t.Fatal(err)
	}
	if err := Upgrade(path); err != nil {
		t.Fatal(err)
	}
	backup, err := os.ReadFile(filepath.Join(dir, "tally.json.v2.bak"))
	if err != nil {
		t.Fatal(err)
	}
	if !bytes.Equal(backup, original) {
		t.Fatal("the backup is not the original file")
	}
	got, err := Load(path)
	if err != nil {
		t.Fatal(err)
	}
	if inv, ok := got.Invoice("org_000001", "in_000010"); !ok || inv.Number != "INV-000003" {
		t.Fatalf("after the upgrade, invoice = %+v", inv)
	}
	b, _ := os.ReadFile(path)
	var head struct {
		Version int `json:"version"`
	}
	if err := json.Unmarshal(b, &head); err != nil || head.Version != 3 {
		t.Fatalf("version after Upgrade = %d, %v", head.Version, err)
	}
	if names := dirNames(t, dir); !reflect.DeepEqual(names, []string{"tally.json", "tally.json.v2.bak"}) {
		t.Fatalf("files = %v", names)
	}
}

