func TestUpgradeLeavesVersion3Alone(t *testing.T) {
	now := time.Date(2026, 2, 1, 12, 0, 0, 0, time.UTC)
	dir := t.TempDir()
	path := filepath.Join(dir, "tally.json")
	if err := Save(store.New(), path, now); err != nil {
		t.Fatal(err)
	}
	before, _ := os.ReadFile(path)
	if err := Upgrade(path); err != nil {
		t.Fatal(err)
	}
	after, _ := os.ReadFile(path)
	if !bytes.Equal(before, after) {
		t.Fatal("Upgrade changed a version 3 file")
	}
	if names := dirNames(t, dir); !reflect.DeepEqual(names, []string{"tally.json"}) {
		t.Fatalf("files = %v; a version 3 file must not get a backup", names)
	}
}

func TestUpgradeRefusesNewerVersions(t *testing.T) {
	dir := t.TempDir()
	path := filepath.Join(dir, "tally.json")
	future := []byte(`{"version": 4, "state": {}}` + "\\n")
	if err := os.WriteFile(path, future, 0o600); err != nil {
		t.Fatal(err)
	}
	if err := Upgrade(path); !errors.Is(err, ErrUnsupportedVersion) {
		t.Fatalf("err = %v", err)
	}
	if _, err := Load(path); !errors.Is(err, ErrUnsupportedVersion) {
		t.Fatalf("Load err = %v", err)
	}
	if b, _ := os.ReadFile(path); !bytes.Equal(b, future) {
		t.Fatal("Upgrade changed a file of a newer version")
	}
	if names := dirNames(t, dir); !reflect.DeepEqual(names, []string{"tally.json"}) {
		t.Fatalf("files = %v", names)
	}
}

func TestUpgradeWillNotOverwriteADifferentBackup(t *testing.T) {
	dir := t.TempDir()
	path := filepath.Join(dir, "tally.json")
	copyFile(t, filepath.Join("testdata", "v2.json"), path)
	original, _ := os.ReadFile(path)
	backup := filepath.Join(dir, "tally.json.v2.bak")
	other := []byte("someone else's backup")
	if err := os.WriteFile(backup, other, 0o600); err != nil {
		t.Fatal(err)
	}
	if err := Upgrade(path); err == nil {
		t.Fatal("Upgrade replaced a backup it did not write")
	}
	if b, _ := os.ReadFile(backup); !bytes.Equal(b, other) {
		t.Fatal("the existing backup changed")
	}
	if b, _ := os.ReadFile(path); !bytes.Equal(b, original) {
		t.Fatal("the file changed although Upgrade failed")
	}
}
